                this.effModal = false;
            } else if (item == 'exp') {
                this.expDate = this.editItem.endDate;
                this.expModal = false;
            } else {
                console.log('Could not reset dialog');
            }
        },
        datePickerReset(item) {
            if (item == 'eff') {
                this.effDate = '';
            } else if (item == 'exp') {
                this.expDate = '';
            } else {
                console.log('Could not reset');
            }
        },
        openEditDialog(item) {
            this.editItem = item;
            this.effDate = item.startDate;
            this.expDate = item.endDate;
            this.editAssetDialog = true;
            this.daysOfWeek.forEach((day) => {
                day.value = false;
            });
            // console.log(item.daysOfWeek);
            if (item.narrativeDisplayPeriod == 'Always') {
                this.daysOfWeek.forEach((day) => {
                    day.value = true;
                });
            } else {
                item.daysOfWeek.forEach((dayInItem) => {
                    this.daysOfWeek.forEach((day) => {
                        if (day.name === dayInItem) {
                            day.value = true;
                        }
                    });
                });
            }
            if (item.startDate == '') {
                this.startDateLabel = 'Enter Date (MM-DD-YYYY)';
            } else {
                this.startDateLabel = item.startDate;
            }
            if (item.endDate == '') {
                this.endDateLabel = 'Enter Date (MM-DD-YYYY)';
            } else {
                this.endDateLabel = item.endDate;
            }
            if (item.startTime == '') {
                this.startTimeLabel = 'Enter Time';
            } else {
                this.startTimeLabel = item.startTime;
            }
            if (item.endTime == '') {
                this.endTimeLabel = 'Enter Time';
            } else {
                this.endTimeLabel = item.endTime;
            }
        },
        async getPreviewItem(item) {
            this.currentTerminal = false;
            console.log(item);
            this.previewTerminal = true;
            if (item.id == this.activeAssetId) {
                this.currentTerminal = true;
            }
            this.previewFile = item.thumbnail;
        },
        async updateTerminalItem() {
            if (this.correctFormat == true) {
                const selectedDays = [];
                this.daysOfWeek.forEach((day) => {
                    // console.log(day);
                    // console.log(day.value);
                    if (day.value == true) {
                        // console.log(day.name);
                        selectedDays.push(day.name);
                    }
                });
                // console.log(selectedDays);
                // console.log(this.editItem.startDate);
                if (this.editItem.padded == true) {
                    // console.log('padded is true');
                    this.editItem.padded = 1;
                } else {
                    // console.log('padded is false');
                    this.editItem.padded = 0;
                }
                if (this.editItem.enabled == true) {
                    // console.log('enabled is true');
                    this.editItem.enabled = 1;
                } else {
                    // console.log('enabled is false');
                    this.editItem.enabled = 0;
                }
                if (this.editItem.preview == true) {
                    // console.log('preview is true');
                    this.editItem.preview = 1;
                } else {
                    // console.log('preview is false');
                    this.editItem.preview = 0;
                }
                if (this.editItem.startDate == undefined) {
                    this.editItem.startDate = this.effDate;
                }
                if (this.editItem.endDate == undefined) {
                    this.editItem.endDate = this.expDate;
                }
                if (this.editItem.startTime == undefined) {
                    this.editItem.startTime = this.item.startTime;
                }
                if (this.editItem.endTime == undefined) {
                    this.editItem.endTime = this.item.endTime;
                }
                if (this.editItem.notes == undefined) {
                    this.editItem.notes = this.item.notes;
                }
                let formData = new FormData();
                formData.append('asset_id', this.editItem.id);
                formData.append('media_id', this.editItem.mediaId);
                formData.append('slide_show_id', this.editItem.slideshowId);
                formData.append('start_date', this.effDate);
                formData.append('end_date', this.expDate);
                formData.append('start_time', this.editItem.startTime);
                formData.append('end_time', this.editItem.endTime);
                formData.append('notes', this.editItem.notes);
                // formData.append('days_of_week[]', selectedDays);
                selectedDays.forEach((day) => {
                    // console.log(day);
                    formData.append('days_of_week[]', day);
                });
                formData.append('padded', this.editItem.padded);
                // formData.append('ordinal', 99);
                formData.append('preview', this.editItem.preview);
                formData.append('enabled', this.editItem.enabled);

                try {
                    let response = await axios.post(
                        `${
                            this.getInternalCoreClearController +
                            '/update_branding_asset'
                        }`,
                        formData,
                        {
                            withCredentials: true,
                            crossDomain: true,
                            headers: {
                                'Content-Type': 'multipart/form-data',
                            },
                        },
                    );
                    console.log(response);
                    if (response.data.success === true) {
                        this.alert = true;
                        this.alertType = 'success';
                        this.alertMessage = 'Asset updated';
                        setTimeout(() => {
                            location.reload();
                        }, 2000);
                    }
                } catch (error) {
                    console.error('Could not update');
                    console.error(error);
                }
            } else {
                this.alert = true;
                this.alertType = 'warning';
                this.alertMessage = 'Invalid format, could not update';
            }
        },

        async getTerminalBrandingList() {
            try {
                let response = await axios.get(
                    `${
                        this.getInternalCoreClearController +
                        '/terminal_branding'
                    }`,
                    {
                        withCredentials: true,
                        crossDomain: true,
                    },
                );

                if (response.data) {
                    console.log(response.data.activeAsset.id);
                    const isActive = response.data.activeAsset.success;

                    if (isActive) {
                        this.activeAssetId = response.data.activeAsset.id;
                    } else {
                        this.assetAlert = true;
                    }
                    console.log(this.previewTerminal);
                    var slideshowArray = response.data.results;
                    for (var name of slideshowArray) {
                        if (name != '') {
                            this.branding.push(name);
                        }
                    }
                } else {
                    this.branding = [];
                    console.log('Branding list not found!');
                }
            } catch (error) {
                console.error('Could not get branding list');
                console.error(error);
            }
        },

        async addMedia() {
            let formData = new FormData();
            // console.log(this.selectedImages);
            if (this.targetSlideShow) {
                // console.log('slideshow is selected');
                formData.append('slide_show_id', this.targetSlideShow.id);
            } else if (this.selectedImages != '') {
                formData.append('media_id', this.selectedImages.id);
            }
            // else {
            //     console.log('fourth case');
            // }

            try {
                let response = await axios.post(
                    `${
                        this.getInternalCoreClearController +
                        '/update_branding_asset'
                    }`,
                    formData,
                    {
                        withCredentials: true,
                        crossDomain: true,
                        headers: {
                            'Content-Type': 'multipart/form-data',
                        },
                    },
                );
                if (response.data) {
                    // console.log('Post');
                    // console.log(this.originalFile[0]);
                    console.log(response.data);
                    this.alert = true;
                    this.alertType = 'success';
                    this.alertMessage = 'Asset added';
                    setTimeout(() => {
                        this.selectedImageUrl = '';
                        location.reload();
                    }, 1500);
                } else {
                    console.log('Branding asset not found!');
                }
            } catch (error) {
                console.error('Could not upload branding asset');
                console.error(error);
            }
            this.reset();
        },
        async deleteItem(item) {
            // console.log(item);
            try {
                let response = await axios.get(
                    `${
                        this.getInternalCoreClearController +
                        '/delete_branding_asset'
                    }`,
                    {
                        params: { asset_id: item.id },
                        withCredentials: true,
                        crossDomain: true,
                    },
                );
                if (response.data) {
                    if (response.data.success === true) {
                        // console.log('deleted');
                        this.imageUsed = false;
                        this.alert = true;
                        this.alertType = 'success';
                        this.alertMessage = 'Asset deleted';
                        setTimeout(() => {
                            location.reload();
                        }, 2000);
                    }
                } else {
                    console.log('Branding asset not found!');
                }
            } catch (error) {
                console.error('Could not delete branding asset');
                console.error(error);
            }
        },
        async getSlideshowList() {
            try {
                let response = await axios.get(
                    `${this.getInternalCoreClearController + '/slide_shows'}`,
                    {
                        withCredentials: true,
                        crossDomain: true,
                    },
                );
                if (response.data) {
                    this.selectSlideShow = response.data.results;

                    // console.log(this.selectSlideShow);
                } else {
                    this.selectSlideShow = [];
                    console.log('Slideshow list not found!');
                }
            } catch (error) {
                console.error('Could not get slideshow list');
                console.error(error);
            }
        },
        async getMediaLibrary(input) {
            try {
                let response = await axios.get(
                    `${this.getInternalCoreClearController + '/get_media'}`,
                    {
                        params: { page: input },
                        withCredentials: true,
                        crossDomain: true,
                    },
                );

                if (response.data) {
                    this.pagesTotal = response.data.pages;
                    const mediaLibrary = response.data.results;
                    // console.log(mediaLibrary);
                    this.library.length = 0;
                    for (let i = 0; i < mediaLibrary.length; i++) {
                        let id = mediaLibrary[i].id;
                        let thumbnailUrl = mediaLibrary[i].thumbnailUrl;

                        this.library.push({
                            id,
                            thumbnailUrl,
                        });
                    }
                } else {
                    this.library = [];
                    console.log('Media library not found!');
                }
            } catch (error) {
                console.error('Could not get media library');
                console.error(error);
                this.alert = true;
                this.alertType = 'error';
                this.alertMessage = error;
            }
        },
        async uploadMedia() {
            // console.log(this.originalFile);
            let formData = new FormData();
            formData.append(
                'upload_media',
                this.originalFile,
                this.originalFile.name,
            );

            try {
                let response = await axios.post(
                    `${this.getInternalCoreClearController + '/upload_media'}`,
                    formData,
                    {
                        withCredentials: true,
                        crossDomain: true,
                        headers: {
                            'Content-Type': 'multipart/form-data',
                        },
                    },
                );

                if (response.data) {
                    if (response.data.success === true) {
                        // console.log(response);
                        this.selectedImages = response.data;
                        this.addMedia();
                    } else {
                        this.alert = true;
                        this.alertType = 'error';
                        this.alertMessage = response.data.responseDescription;
                    }
                } else {
                    console.log('Unable to upload');
                }
            } catch (error) {
                console.error('Could not upload media');
                console.error(error);
            }
        },

        selectImage(image) {
            // console.log(key);
            // console.log(image.thumbnailUrl);
            this.selectedImages = image;
            this.selectedImageUrl = image.thumbnailUrl;
            this.selectedId = image.id;
        },
        slideshowSelection(item) {
            const selectedSlideshowObj = this.selectSlideShow.find(
                (slideshow) => slideshow.name === item,
            );

            if (selectedSlideshowObj) {
                this.targetSlideShow = selectedSlideshowObj;
                // console.log(this.targetSlideShow);
            } else {
                console.log('Selected Slideshow not found!');
            }
        },
        // updateSelectedDate() {
        //     this.selectedDate = this.manualDate;
        // },

        // updateManualDate() {
        //     this.manualDate = this.selectedDate;
        // },
        checkExclusiveValue(value) {
            if (value === 'enabled' && this.editItem.enabled === true) {
                this.$nextTick(() => {
                    this.editItem.preview = false;
                    this.$forceUpdate();
                });
            } else if (value === 'preview' && this.editItem.preview === true) {
                this.$nextTick(() => {
                    this.editItem.enabled = false;
                    this.$forceUpdate();
                });
            } else {
                console.log('problem occurred');
            }
        },

        validateFormat(item) {
            // console.log(item);
            const timePattern = /^$|^(?:[0-9]{1,2}):[0-5][0-9]$/;
            const datePattern =
                /^$|^(?:(?:0[1-9]|1[0-2])\/(0[1-9]|[12][0-9]|3[01])\/\d{4}|(?:\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01]))$/;

            if (item == 'startTime') {
                if (!timePattern.test(this.editItem.startTime)) {
                    this.startTimeError = [
                        'Invalid time format. Use XX:XX or X:XX.',
                    ];
                    this.correctFormat = false;
                } else {
                    this.startTimeError = [];
                    this.correctFormat = true;
                }
            } else if (item == 'endTime') {
                if (!timePattern.test(this.editItem.endTime)) {
                    this.endTimeError = [
                        'Invalid time format. Use XX:XX or X:XX.',
                    ];
                    this.correctFormat = false;
                } else {
                    this.endTimeError = [];
                    this.correctFormat = true;
                }
            } else if (item == 'startDate') {
                if (!datePattern.test(this.editItem.startDate)) {
                    this.startDateError = [
                        'Invalid date format. Use MM/DD/YYYY or YYYY-MM-DD.',
                    ];
                    this.correctFormat = false;
                } else {
                    this.startDateError = [];
                    this.correctFormat = true;
                }
            } else if (item == 'endDate') {
                if (!datePattern.test(this.editItem.endDate)) {
                    this.endDateError = [
                        'Invalid date format. Use MM/DD/YYYY or YYYY-MM-DD.',
                    ];
                    this.correctFormat = false;
                } else {
                    this.endDateError = [];
                    this.correctFormat = true;
                }
            }
            // else {
            //     console.log('fifth condition');
            // }
        },
        reset() {
            this.$refs.uploadForm.reset();
        },
    },
};
</script>
